const inputData = $input.first().json;
const isCron = !inputData.body && !inputData.url;
const body = inputData.body || inputData;

// 1. URL do produto enviada pelo MarcFlow
const productUrl = body.url || body.productUrl || '';
const tag = body.tag || 'venddor17';
const productId = body.productId || '';

// 2. Cookie armazenado estaticamente ou enviado no body
const staticData = $getWorkflowStaticData('global');
let currentCookie = body.cookie || staticData.meliCookie || '';

return {
  json: {
    isCron,
    productUrl,
    tag,
    productId,
    cookie: currentCookie,
    hasCookie: Boolean(currentCookie && currentCookie.length > 20)
  }
};

const originalData = $('Preparar Dados e Cookies').first().json;
const prevCookie = originalData.cookie || '';

const response = $input.first().json;
const headers = response.headers || {};
const setCookieHeader = headers['set-cookie'] || [];

function parseCookies(cookieStr) {
  const map = new Map();
  if (!cookieStr) return map;
  const parts = cookieStr.split(';');
  for (const part of parts) {
    const pair = part.trim();
    if (!pair) continue;
    const eqIdx = pair.indexOf('=');
    if (eqIdx > 0) {
      const k = pair.substring(0, eqIdx).trim();
      const v = pair.substring(eqIdx + 1).trim();
      map.set(k, v);
    }
  }
  return map;
}

const cookieMap = parseCookies(prevCookie);
const setCookies = Array.isArray(setCookieHeader) ? setCookieHeader : [setCookieHeader];
for (const sc of setCookies) {
  if (!sc || typeof sc !== 'string') continue;
  const firstPart = sc.split(';')[0].trim();
  const eqIdx = firstPart.indexOf('=');
  if (eqIdx > 0) {
    const k = firstPart.substring(0, eqIdx).trim();
    const v = firstPart.substring(eqIdx + 1).trim();
    cookieMap.set(k, v);
  }
}

const mergedList = [];
for (const [k, v] of cookieMap.entries()) {
  mergedList.push(`${k}=${v}`);
}
const updatedCookie = mergedList.join('; ');

const staticData = $getWorkflowStaticData('global');
if (updatedCookie.length > 20) {
  staticData.meliCookie = updatedCookie;
}

return {
  json: {
    isCron: originalData.isCron,
    productUrl: originalData.productUrl,
    tag: originalData.tag,
    productId: originalData.productId,
    cookie: updatedCookie
  }
};

const resp = $input.first().json;
const reqData = $('Merge Cookies (Júlio Borges)').first().json;

const body = resp.body || resp;
let shortUrl = '';

if (Array.isArray(body)) {
  shortUrl = body[0]?.short_url || body[0]?.shortUrl || body[0]?.url || '';
} else if (body && typeof body === 'object') {
  if (Array.isArray(body.urls) && body.urls[0]) {
    shortUrl = body.urls[0].short_url || body.urls[0].shortUrl || body.urls[0].url || '';
  } else {
    shortUrl = body.short_url || body.shortUrl || body.url || body.link || '';
  }
}

const ok = Boolean(shortUrl && shortUrl.startsWith('http'));

return {
  json: {
    ok,
    affiliateUrl: shortUrl || '',
    productId: reqData.productId,
    productUrl: reqData.productUrl,
    tag: reqData.tag,
    status: resp.statusCode || 200,
    error: ok ? null : (body?.message || 'Falha ao obter shortUrl do Mercado Livre')
  }
};

